import java.util.*;
import java.io.*;
import java.awt.*;

public class Paint {
    private static final char[] OPEN_DOORS = {'-'};
    private static final char[] WALLS_AND_CLOSED_DOORS = {'X', '='};
    private static final int[][] dirs =
        { {-1, 0, 1, 0}, {0, 1, 0, -1} };

    public static void main(String[] args) throws Exception{
        Scanner s = new Scanner(new File("paint.dat"));
        int numSets = s.nextInt();
        s.nextLine();
        int lines;
        String[] tempLines;
        char[][] map;
        boolean[][] beenThere;
        for(int i = 0; i < numSets; i++){
            lines = s.nextInt();
            s.nextLine();
            tempLines = new String[lines];
            for(int j = 0; j < lines; j++){
                tempLines[j] = s.nextLine();
            }
            map = formMap(tempLines);
            Point start = getStart(tempLines);
            beenThere = new boolean[map.length][maxRowLength(map)];
            char[][] originalMap = makeCopyOfMap(map);
            paint(map, originalMap, beenThere, start.y, start.x);
            show(map);
            System.out.println(paintNeeded(map));
            System.out.println();
        }
        s.close();
    }

    private static char[][] makeCopyOfMap(char[][] map) {
        char[][] result = new char[map.length][];
        for(int row = 0; row < map.length; row++){
            result[row] = map[row].clone();

        }
        return result;
    }

    private static int maxRowLength(char[][] map) {
        int max = 0;
        for(int r = 0; r < map.length; r++)
            max = map[r].length > max ? map[r].length : max;
        return max;
    }

    private static void paint(char[][] map,
                              char[][] originalMap,
                              boolean[][] beenThere,
                              int row,
                              int col) {
        //if I am out of bounds, return
        if(row < 0 || row >= map.length || col < 0 || col >= map[row].length)
            return;
        //if I have been here before, return
        if( beenThere[row][col] )
            return;
        //mark that I have been here
        beenThere[row][col] = true;
        //if this is a wall or closed door, return
        char c = originalMap[row][col];
        if( c == 'X' || c == '=')
            return;
        //should I mark this with a C or a W?
        if( c == '-' || borders(originalMap, row, col, OPEN_DOORS))
            map[row][col] = 'C';
        else if( borders(originalMap, row, col, WALLS_AND_CLOSED_DOORS) )
            map[row][col] = 'W';
        else
            map[row][col] = 'C';
        // move up, right, down, and left to explore the area
        for(int i = 0; i < dirs[0].length; i++){
            paint(map, originalMap, beenThere, row + dirs[0][i], col + dirs[1][i]);
        }
    }

    private static boolean borders(char[][] map, int row, int col, char[] targets) {
        boolean isOpen = false;
        int r, c;
        for(int i = 0; i < dirs[0].length && !isOpen; i++){
            r = row + dirs[0][i];
            c = col + dirs[1][i];
            if( r >= 0 && r < map.length && c >= 0 && c < map[r].length){
                for(int j = 0; j < targets.length; j++)
                    if( targets[j] == map[r][c] )
                        isOpen = true;
            }
        }
        return isOpen;
    }

    private static Point getStart(String[] map) {
        for(int r = 0; r < map.length; r++){
            if( map[r].contains("*") )
                return new Point(map[r].indexOf('*'), r);
        }
        return null;
    }

    private static char[][] formMap(String[] tempLines) {
        char[][] result = new char[tempLines.length][];
        int limit;
        for(int r = 0; r < tempLines.length; r++){
            limit = tempLines[r].length();
            result[r] = new char[limit];
            for(int c = 0; c < limit; c++)
                result[r][c] = tempLines[r].charAt(c);
        }
        return result;
    }

    public static void show(char[][] map){
        for(int r = 0; r < map.length; r++){
            for(int c = 0; c < map[r].length; c++)
                System.out.print( map[r][c]);
            System.out.println();
        }
    }

    public static int paintNeeded(char[][] map){
        double accum = 0;
        for(int r = 0; r < map.length; r++){
            for(int c = 0; c < map[r].length; c++){
                if( map[r][c] == 'W' )
                    accum += 2;
                else if( map[r][c] == 'C' )
                    accum += 1;
            }
        }
        return (int)Math.ceil(accum / 10.0);
    }


}

import java.io.*;
import java.util.*;

public class Pyramid {
    public static void main(String[] args) throws IOException{
        Scanner s = new Scanner(new File("pyramid.dat"));
        int numSets = s.nextInt();
        s.nextLine();
        
        for(int i = 1; i <= numSets; i++){
            int rows = s.nextInt();
            int cols = s. nextInt();
            int[][] plan = getPlan(rows, cols, s);
            int numRings = getNumRings(rows, cols);
            //System.out.println(numRings);
            boolean build = true;
            int ring = 0;
            int max = getMax(ring, plan);
            int min;
            ring++;
            while( ring < numRings && build){
                min = getMin(ring, plan);
                //System.out.println("min: " + min + ", max: " + max);
                build = max < min;
                max = getMax(ring, plan);
                ring++;
            }
            if( build )
                System.out.println("BUILD IT");
            else
                System.out.println("SCRAP IT");
        }
    }

    private static int getMin(int ring, int[][] plan) {
        int topRow = ring;
        int bottomRow = plan.length - ring - 1;
        int leftCol = ring;
        int rightCol = plan[0].length - ring - 1;
        int min = Integer.MAX_VALUE;
        //System.out.println("Get min topRow, bottomRow, leftCol, rightCol: " + topRow + " " + bottomRow + " " + leftCol + " " + rightCol);
        for(int rowNum = topRow; rowNum <= bottomRow; rowNum++){
            min = Math.min(min, plan[rowNum][leftCol]);
            min = Math.min(min, plan[rowNum][rightCol]);
        }
        for(int colNum = leftCol; colNum <= rightCol; colNum++){
            min = Math.min(min, plan[topRow][colNum]);
            min = Math.min(min, plan[bottomRow][colNum]);
        }
        return min;
    }

    private static int getMax(int ring, int[][] plan) {
        int topRow = ring;
        int bottomRow = plan.length - ring - 1;
        int leftCol = ring;
        int rightCol = plan[0].length - ring - 1;
        //System.out.println("Get max topRow, bottomRow, leftCol, rightCol: " + topRow + " " + bottomRow + " " + leftCol + " " + rightCol);
        
        int max = Integer.MIN_VALUE;
        for(int rowNum = topRow; rowNum <= bottomRow; rowNum++){
            max = Math.max(max, plan[rowNum][leftCol]);
            max = Math.max(max, plan[rowNum][rightCol]);
        }
        for(int colNum = leftCol; colNum <= rightCol; colNum++){
            max = Math.max(max, plan[topRow][colNum]);
            max = Math.max(max, plan[bottomRow][colNum]);
        }
        return max;
    }

    private static int getNumRings(int rows, int cols) {
        int r = 0, c = 0;
        r = rows % 2 == 0 ? rows / 2 : rows / 2 + 1;
        c = cols % 2 == 0 ? cols / 2 : cols / 2 + 1;
        return Math.min(r, c);
    }

    private static int[][] getPlan(int rows, int cols, Scanner s) {
        int[][] result = new int[rows][cols];
        for(int r = 0; r < rows; r++){
            for(int c = 0; c < cols; c++)
                result[r][c] = s.nextInt();
        }
        return result;
    }
}

